63	impl AsTable for Relation {
64	    /// The `Table` with the foreign keys are written. Can either be:
65	    ///
66	    /// - A separate table for many-to-many relations.
67	    /// - One of the model tables for one-to-many or one-to-one relations.
68	    /// - A separate relation table for all relations, if using the deprecated
69	    ///   data model syntax.
70	    fn as_table(&self, ctx: &Context<'_>) -> Table<'static> {
71	        match self.walker().refine() {
72	            // In this case we must define our unique indices for the relation
73	            // table, so MSSQL can convert the `INSERT .. ON CONFLICT IGNORE` into
74	            // a `MERGE` statement.
75	            walkers::RefinedRelationWalker::ImplicitManyToMany(ref m) => {
76	                let model_a = m.model_a();
77	                let prefix = model_a.schema_name().unwrap_or_else(|| ctx.schema_name()).to_owned();
78	                let table: Table = (prefix, m.table_name().to_string()).into();
79	
80	                table.add_unique_index(vec![Column::from("A"), Column::from("B")])
81	            }
82	            walkers::RefinedRelationWalker::Inline(ref m) => {
83	                self.dm.find_model_by_id(m.referencing_model().id).as_table(ctx)
84	            }
85	            walkers::RefinedRelationWalker::TwoWayEmbeddedManyToMany(_) => {
86	                unreachable!("TwoWayEmbeddedManyToMany relation in sql-query-connector")
87	            }
88	        }
89	    }
90	}
